// Eligibility triage (no messages sent here).
// eligible: approved before | needs-approval: scraped number with source URL |
// ineligible: no number, opted out, or suppressed.
const items = $input.first().json;
const list = Array.isArray(items) ? items : (items.items || []);
return list.flatMap((c) => (c.contacts || []).map((ct) => ({ json: {
  company_id: c.id, company: c.company_name, contact_id: ct.id,
  number: ct.whatsapp_number || ct.phone,
  eligible: ct.whatsapp_eligible === true,
  opted_out: ct.consent_status === 'opted_out',
  source_url: ct.whatsapp_source_url || ct.email_source_url || null,
  verdict: ct.whatsapp_eligible === true ? 'eligible'
    : ct.consent_status === 'opted_out' ? 'ineligible-opted-out'
    : (ct.whatsapp_source_url || ct.email_source_url) ? 'needs-approval' : 'ineligible-no-evidence'
} })));
